def board(proj, name, title, w, h, body, css=''):
    with open(os.path.join(proj, name + '.dc.html'), 'w', encoding='utf-8') as f:
        f.write(HEAD % (title, css, body, w, h))

# ---------- nét vẽ cơ bản ----------
def st(w=7): return 'stroke="%s" stroke-width="%s" stroke-linejoin="round" stroke-linecap="round"' % (K, w)
def P(d, f='none', w=7): return '<path d="%s" fill="%s" %s/>' % (d, f, st(w))
def F(d, f): return '<path d="%s" fill="%s"/>' % (d, f)
def L(d, c=K, w=7): return '<path d="%s" fill="none" stroke="%s" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round"/>' % (d, c, w)
def E(cx, cy, rx, ry=None, f='none', w=7, rot=0):
    ry = rx if ry is None else ry
    r = ' transform="rotate(%s %s %s)"' % (rot, cx, cy) if rot else ''
    return '<ellipse cx="%s" cy="%s" rx="%s" ry="%s" fill="%s" %s%s/>' % (cx, cy, rx, ry, f, st(w), r)
def EF(cx, cy, rx, ry, f, rot=0):
    r = ' transform="rotate(%s %s %s)"' % (rot, cx, cy) if rot else ''
    return '<ellipse cx="%s" cy="%s" rx="%s" ry="%s" fill="%s"%s/>' % (cx, cy, rx, ry, f, r)
def R(x, y, w_, h, f, r=0, sw=7, rot=None):
    t = ' transform="rotate(%s %s %s)"' % rot if rot else ''
    return '<rect x="%s" y="%s" width="%s" height="%s" rx="%s" fill="%s" %s%s/>' % (x, y, w_, h, r, f, st(sw), t)
def HL(d, c='#fff', w=11, op=.75): return '<path d="%s" fill="none" stroke="%s" stroke-width="%s" stroke-linecap="round" opacity="%s"/>' % (d, c, w, op)
def G(s, t): return '<g transform="%s">%s</g>' % (t, s)
def SH(y=356, rx=104): return '<ellipse cx="200" cy="%s" rx="%s" ry="13" fill="%s" opacity=".16"/>' % (y, rx, K)
def ball(cx, cy, rx, ry, f, s, hi='#fff'):
    # khối tròn: tô nền + mảng tối bên phải + viền + một vệt sáng
    o = EF(cx, cy, rx, ry, f) + F('M%s %sA%s %s 0 0 1 %s %sA%s %s 0 0 0 %s %sZ' % (cx + rx * .1, cy - ry, rx, ry, cx + rx * .1, cy + ry, rx * .6, ry, cx + rx * .1, cy - ry), s)
    o += E(cx, cy, rx, ry)
    if hi: o += HL('M%.0f %.0fQ%.0f %.0f %.0f %.0f' % (cx - rx * .68, cy - ry * .1, cx - rx * .62, cy - ry * .62, cx - rx * .18, cy - ry * .72), hi)
    return o
def eye(x, y, r=11):
    return '<circle cx="%s" cy="%s" r="%s" fill="#2A1A14"/><circle cx="%s" cy="%s" r="%.1f" fill="#fff"/>' % (x, y, r, x - r * .3, y - r * .35, r * .33)
def wheel(x, y, r, c='#3A3540', hub='#E7DFC9'):
    return E(x, y, r, r, c) + E(x, y, r * .45, r * .45, hub, 5)

