def person(hair_back, hair_front, body, skin='#EDBF94', cy=150, extra=''):
    o = SH0 + hair_back + body
    o += E(200, cy, 86, 86, skin) + F('M262 %d A86 86 0 0 1 214 %d Q270 %d 262 %d Z' % (cy - 58, cy + 84, cy + 40, cy - 58), '#D9A274')
    o += hair_front + eye(166, cy + 8) + eye(234, cy + 8) + EF(200, cy + 32, 6, 4.5, '#B8743F') + extra
    return o
