def s_crab():
    o = SH0
    for sg in (-1, 1):
        for k in range(3):
            o += L('M%d %dQ%d %d %d %d' % (200 + sg * 80, 256 + k * 14, 200 + sg * 150, 262 + k * 16, 200 + sg * (146 - k * 14), 330 + k * 8), K, 11)
        o += L('M%d 214Q%d 180 %d 160' % (200 + sg * 92, 200 + sg * 136, 200 + sg * 124), K, 14) + L('M%d 214Q%d 180 %d 160' % (200 + sg * 92, 200 + sg * 136, 200 + sg * 124), '#E2483E', 6)
        o += P('M%d 168C%d 132 %d 92 %d 84C%d 88 %d 104 %d 122L%d 118C%d 96 %d 78 %d 84C%d 100 %d 150 %d 168Z' % (200 + sg * 124, 200 + sg * 168, 200 + sg * 158, 200 + sg * 120, 200 + sg * 108, 200 + sg * 112, 200 + sg * 118, 200 + sg * 126, 200 + sg * 130, 200 + sg * 148, 200 + sg * 150, 200 + sg * 176, 200 + sg * 172, 200 + sg * 124), '#E2483E')
        o += L('M%d 216V166' % (200 + sg * 36), K, 7) + E(200 + sg * 36, 158, 18, 18, '#FFF3D6', 6) + eye(200 + sg * 36, 159, 9)
    return o + ball(200, 262, 118, 76, '#E8604C', '#B3261E', '#FFB0A0')
