# ---------- số đếm ----------
def number(n, c, dark):
    o = '<text x="200" y="%d" text-anchor="middle" font-family="Be Vietnam Pro" font-weight="800" font-size="210" fill="%s" stroke="%s" stroke-width="7" paint-order="stroke" stroke-linejoin="round">%d</text>' % (222, c, K, n)
    top = min(n, 5); bot = n - top
    for row, cnt in ((0, top), (1, bot)):
        for k in range(cnt):
            x, y = 200 + (k - (cnt - 1) / 2) * 62, (262 if bot else 292) + row * 62
            o += E(x, y, 25, 25, c) + HL('M%d %dQ%d %d %d %d' % (x - 13, y, x - 11, y - 11, x, y - 13), '#fff', 6)
    return o

