def s_trophy():
    o = SH(360, 110) + L('M112 92C24 92 50 214 130 208M288 92C376 92 350 214 270 208', K, 25) + L('M112 92C24 92 50 214 130 208M288 92C376 92 350 214 270 208', '#F2B83A', 11)
    d = 'M100 44H300C310 158 276 244 200 248C124 244 90 158 100 44Z'
    o += F(d, '#FFD04A') + F('M246 44H300C310 158 276 244 200 248C260 200 268 110 246 44Z', '#E8A92E') + P(d) + P('M180 244H220V290H180Z', '#E8A92E') + R(112, 288, 176, 64, '#6B4A32', 10) + R(146, 306, 108, 26, '#FFD04A', 4, 5)
    return o + P('M200 90L213 124H250L220 146L232 182L200 160L168 182L180 146L150 124H187Z', '#FFF3B0', 5) + HL('M124 76Q126 136 148 186', '#FFF3B0', 11)

# ---------- danh mục ----------
DRAW = {
    'one': lambda: number(1, '#E2483E', ''), 'two': lambda: number(2, '#F7913A', ''), 'three': lambda: number(3, '#F7D24A', ''), 'four': lambda: number(4, '#4CC768', ''), 'five': lambda: number(5, '#3C8FD6', ''),
    'six': lambda: number(6, '#8E5AA8', ''), 'seven': lambda: number(7, '#F268A6', ''), 'eight': lambda: number(8, '#2FA6A0', ''), 'nine': lambda: number(9, '#E8913A', ''), 'ten': lambda: number(10, '#E2384E', ''),
    'red': lambda: splash('#E2382E', '#AE1E1A'), 'blue': lambda: splash('#2F7FD6', '#1C5AA8'), 'yellow': lambda: splash('#FFD93A', '#E8AE1A'), 'green': lambda: splash('#3CB85A', '#22863E'), 'pink': lambda: splash('#F77AB0', '#D04A88'),
}
for _k, _v in list(globals().items()):
    if _k.startswith('s_') and callable(_v): DRAW.setdefault(_k[2:], _v)

def load_words():
    txt = ''.join(open(os.path.join(ROOT, 'src/shared', f), encoding='utf-8').read() for f in ('pictures.ts', 'picturesMore.ts', 'pictureExtras.ts'))
    vi = dict(re.findall(r"'?([a-z]+)'?: \{ en: '[^']*', vi: '([^']*)'", txt))
    t1, rest = [], []
    for f in sorted(glob.glob(os.path.join(ROOT, 'content/curated/kids/world/places/*.json'))):
        d = json.load(open(f, encoding='utf-8'))
        (t1 if d['place']['tier'] == 'vn' else rest).extend(x['picture'] for x in d['words'])
    return t1, rest, vi

def tile(word, vi):
    return ('<div class="cd"><svg width="172" height="168" viewBox="10 10 380 370" role="img" aria-label="%s">%s</svg><div class="w">%s</div><div class="m">%s</div></div>' % (word, DRAW[word](), word, vi))

CSS = """.cd{width:194px;height:244px;background:#FFF9EA;border:3px solid #6B3E1E;border-radius:16px;box-shadow:0 5px 0 #6B3E1E;padding:6px 4px 4px;text-align:center}
.cd svg{display:block;margin:0 auto}
.w{font-weight:800;font-size:22px;line-height:1.15;color:#D32F2F;margin-top:2px}
.m{font-size:14px;font-weight:600;line-height:1.3}
.gr{display:grid;grid-template-columns:repeat(8,194px);gap:18px 14px}"""
W, H = 1724, 1436

def main(proj):
    sys.stdout.reconfigure(encoding='utf-8')
    t1, rest, vi = load_words()
    order = t1 + rest
    drawn = [w for w in order if w in DRAW]
    miss = [w for w in order if w not in DRAW]
    n = math.ceil(len(drawn) / 40)
    for k in range(n):
        part = drawn[k * 40:(k + 1) * 40]
        body = '<div class="v" style="width:%dpx;height:%dpx;padding:26px 36px"><div class="t1" style="font-size:32px;margin-bottom:6px">Thẻ từ Kids World %d/%d</div><div style="font-size:15px;margin-bottom:16px">Nét chuẩn R6Cards: viền nâu, tô 2 mảng, một vệt sáng. Đồ vật không mặt, con vật giữ mắt và mũi.</div><div class="gr">%s</div></div>' % (W, H, k + 1, n, ''.join(tile(w, vi.get(w, '')) for w in part))
        board(proj, 'CCards%d' % (k + 1), 'Thẻ từ %d' % (k + 1), W, H, body, CSS)
    print('tầng 1: %d/%d | còn lại: %d/%d | bảng: %d' % (sum(w in DRAW for w in t1), len(t1), sum(w in DRAW for w in rest), len(rest), n))
    print('chưa vẽ:', ' '.join(miss) or '(không)')

if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else os.environ['BOARD_OUT'])
